import { signal, Text, View } from "nsh";
import W_R40 from "./R40";
import W_R39 from "./R39";

// Regenerated by tools/gen-server.mjs whenever a widget is published or
// removed. The Work tab renders this shelf — each card is a frozen copy of a
// published generated module.

const GEN = "http://127.0.0.1:8787";
const post = (path: string, body: object) =>
  fetch(`${GEN}${path}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  }).catch(() => null);

export function WidgetShelf() {
  const sent = signal("");
  const sendToChat = (name: string) =>
    post("/reuse", { name }).then(() => {
      sent.set(name);
      setTimeout(() => sent.set(""), 1500);
    });
  const unpublish = (name: string) => post("/unpublish", { name });
  return (
    <View class="gap-3 px-4 py-4">
      <Text style={{ color: "#6e6e73", fontSize: 12, fontWeight: "600" }}>
        PUBLISHED WIDGETS — 2
      </Text>
      
      <View class="rounded-2xl border border-[#2a2a2a] bg-[#181818] p-3">
        <View class="flex-row items-center justify-between pb-2">
          <View>
            <Text style={{ color: "#ececec", fontSize: 13, fontWeight: "600" }}>{"of implicit any errors: add type annotations to parameters."}</Text>
            <Text style={{ color: "#6e6e73", fontSize: 10 }}>{"R40.tsx · published 2026-10-17"}</Text>
          </View>
          <View class="flex-row gap-2">
            <View onPress={() => sendToChat("R40")} activeOpacity={0.7} style={{ borderRadius: 8, paddingHorizontal: 9, paddingVertical: 5, backgroundColor: "#2f2f2f" }}>
              <Text style={{ color: "#ececec", fontSize: 11 }}>{sent() === "R40" ? "＋ chat ✓" : "＋ chat"}</Text>
            </View>
            <View onPress={() => unpublish("R40")} activeOpacity={0.7} style={{ borderRadius: 8, paddingHorizontal: 9, paddingVertical: 5 }}>
              <Text style={{ color: "#6e6e73", fontSize: 11 }}>✕</Text>
            </View>
          </View>
        </View>
        <W_R40 />
      </View>

      <View class="rounded-2xl border border-[#2a2a2a] bg-[#181818] p-3">
        <View class="flex-row items-center justify-between pb-2">
          <View>
            <Text style={{ color: "#ececec", fontSize: 13, fontWeight: "600" }}>{"**Pomodoro timer:** 25-minute focus sessions. Completed sessions and total focus minutes are saved."}</Text>
            <Text style={{ color: "#6e6e73", fontSize: 10 }}>{"R39.tsx · published 2026-10-17"}</Text>
          </View>
          <View class="flex-row gap-2">
            <View onPress={() => sendToChat("R39")} activeOpacity={0.7} style={{ borderRadius: 8, paddingHorizontal: 9, paddingVertical: 5, backgroundColor: "#2f2f2f" }}>
              <Text style={{ color: "#ececec", fontSize: 11 }}>{sent() === "R39" ? "＋ chat ✓" : "＋ chat"}</Text>
            </View>
            <View onPress={() => unpublish("R39")} activeOpacity={0.7} style={{ borderRadius: 8, paddingHorizontal: 9, paddingVertical: 5 }}>
              <Text style={{ color: "#6e6e73", fontSize: 11 }}>✕</Text>
            </View>
          </View>
        </View>
        <W_R39 />
      </View>
    </View>
  );
}
